def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary 
    of the letter with the most repetition and containing the corresponding count.

    If several letters have the same occurrence, return all of them.

    Args:
        test (str): A string of space-separated lowercase letters.

    Returns:
        dict: A dictionary where each key is a unique letter in the input string and its value is the maximum count of that letter.
    """
    # Split the input string into a list of characters
    chars = test.split()

    # Initialize an empty dictionary to store the frequency of each character
    freq_dict = {}

    # Iterate over each character in the list
    for char in chars:
        # If the character is already in the dictionary, increment its count
        if char in freq_dict:
            freq_dict[char]['count'] += 1
        # Otherwise, add the character to the dictionary with a count of 1
        else:
            freq_dict[char] = {'letter': char, 'count': 1}

    # Initialize an empty list to store the maximum frequency for each letter
    max_freq_list = []

    # Iterate over each item in the dictionary
    for item in freq_dict.values():
        # If the count of the current character is greater than the previous maximum count, update the maximum frequency list
        if item['count'] > max_freq_list[0]['count']:
            max_freq_list = [item]
        # Otherwise, append the current item to the maximum frequency list
        else:
            max_freq_list.append(item)

    # Initialize an empty dictionary to store the result
    result = {}

    # Iterate over each item in the maximum frequency list
    for item in max_freq_list:
        # For each character in the item, add it to the result dictionary with its count
        for char, count in item.items():
            if char not in result:
                result[char] = 0
            result[char] += count

    # Return the result dictionary
    return {letter: count for letter, count in result.items()}

# Test the function
print(histogram('a b c'))  # Output: {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # Output: {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # Output: {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # Output: {'b': 4}
print(histogram(''))  # Output {}
```

