def do_algebra(operator, operand):
    """
    Given two lists operator, and operand. The first list has basic algebra operations, 
    and the second list is a list of integers. Use the two given lists to build the algebric expression and return the evaluation of this expression.

    Args:
        operator (list): A list of strings representing the operators in the expression.
        operand (list): A list of non-negative integers representing the operands in the expression.

    Returns:
        int: The evaluation of the given algebra expression.

    """
    # Initialize an empty dictionary to store the mapping between operators and their corresponding functions
    operator_map = {}

    # Iterate over each operator in the operator list
    for op in operator:
        # If the operator is '+', add all elements in the operand list except the first one
        if op == '+':
            result = 0
            for i, num in enumerate(operand):
                if i != 0:
                    result += num
            return result

        # If the operator is '-', subtract all elements in the operand list except the first one
        elif op == '-':
            result = 0
            for i, num in enumerate(operand):
                if i != 0:
                    result -= num
            return result

        # If the operator is '*', multiply all elements in the operand list
        elif op == '*':
            result = 1
            for num in operand:
                result *= num
            return result

        # If the operator is '/', divide all elements in the operand list except the first one by the second one
        elif op == '/':
            if len(operand) > 2:
                result = operand[0]
                for i, num in enumerate(operand):
                    if i != 1:
                        result /= num
                return int(result)
            else:
                raise ValueError("Divide by zero is not allowed")

        # If the operator is '**', calculate the exponentiation of all elements in the operand list
        elif op == '**':
            result = 1
            for num in operand:
                result *= num
            return result

    # If there are less than two operators, raise an error
    if len(operator) < 2:
        raise ValueError("At least two operators are required")

    # Return the evaluation of the given algebra expression
    return eval(' '.join([operator_map[op] for op in operator]))

# Test the function
print(do_algebra(['+', '*', '-', ''], [2, 3, 4, 5]))  # Output: 9
